import asyncio, sys, re, json
from playwright.async_api import async_playwright
OUT = "/Users/jonasstenglein/.claude/jobs/064ce75e/tmp/scout-a/"
TP = "https://atira-rfq-tender-portal.kyora.run"
MAIL = "https://atira-rfq-mail.kyora.run"
USER = "u_9c3cb06a5d21b197"
TP_PW = "REDACTED"
MAIL_PW = "REDACTED"
async def dump(page, name, shot=True):
    html = await page.content()
    open(OUT+name+".html","w").write(html)
    txt = await page.evaluate("document.body ? document.body.innerText : ''")
    open(OUT+name+".txt","w").write(page.url+"\n"+txt)
    if shot: await page.screenshot(path=OUT+name+".png", full_page=True)
    print("=== ", name, page.url); print(txt[:3000])

async def tp_login(ctx):
    page = await ctx.new_page()
    await page.goto(TP, wait_until="domcontentloaded")
    if "/login" in page.url:
        await page.fill("input[name=username]", USER)
        await page.fill("input[name=password]", TP_PW)
        await page.click("button[type=submit]")
        await page.wait_for_load_state("domcontentloaded")
    if "/consent" in page.url:
        await page.click("button[type=submit]")
        await page.wait_for_load_state("domcontentloaded")
    return page

async def info(page):
    links = await page.eval_on_selector_all("a", "els=>els.map(e=>[e.innerText.trim(), e.getAttribute('href')])")
    forms = await page.eval_on_selector_all("form", "els=>els.map(e=>e.outerHTML.replace(/\\s+/g,' ').slice(0,1500))")
    ifr = await page.eval_on_selector_all("iframe", "els=>els.map(e=>e.getAttribute('src'))")
    print("LINKS", links); print("FORMS", forms); print("IFRAMES", ifr)

async def close_overlays(page):
    await page.evaluate("""()=>{document.querySelectorAll('dialog[open]').forEach(d=>d.close());
      document.querySelectorAll('[data-download]').forEach(d=>d.hidden=true);}""")

async def mail_login(ctx):
    page = await ctx.new_page()
    await page.goto(MAIL, wait_until="domcontentloaded")
    if "/login" in page.url:
        await page.fill("input[name=username]", USER)
        await page.fill("input[name=password]", MAIL_PW)
        await page.click("button[type=submit]")
        await page.wait_for_load_state("domcontentloaded")
    if "/consent" in page.url:
        await page.click("button[type=submit]")
        await page.wait_for_load_state("domcontentloaded")
    await page.wait_for_timeout(1300); await close_overlays(page)
    return page
from common import *
async def frames_dump(page, name):
    for i,f in enumerate(page.frames):
        try:
            t = await f.evaluate("document.body ? document.body.innerText : ''")
            h = await f.content()
        except Exception as e:
            t = h = str(e)
        open(OUT+f"{name}_f{i}.txt","w").write(f.url+"\n"+t)
        open(OUT+f"{name}_f{i}.html","w").write(h)
        print(f"--- frame {i} {f.url} parent={f.parent_frame.url if f.parent_frame else None}\n{t[:6000]}")
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(headless=True)
        ctx = await b.new_context(viewport={"width":1280,"height":800}, accept_downloads=True)
        page = await tp_login(ctx)
        await page.goto(TP+"/tenders/VG-2027-7093?tab=questions"); await page.wait_for_load_state("networkidle")
        await frames_dump(page, "tp_qa")
        await page.goto(TP+"/tenders/VG-2027-7093?tab=documents"); await page.wait_for_load_state("networkidle")
        await frames_dump(page, "tp_docs")
        for i in range(3):
            r = await ctx.request.get(TP+f"/tenders/VG-2027-7093/documents/{i}")
            print(f"### doc {i}", r.status, r.headers.get("content-type")); t=await r.text(); open(OUT+f"tp_doc{i}.html","w").write(t); print(t[:3000])
        r = await ctx.request.get(TP+"/tenders/VG-2027-7093/documents.zip")
        print("ZIP", r.status, r.headers.get("content-type")); open(OUT+"tp_docs.zip","wb").write(await r.body())
        await b.close()
asyncio.run(main())
