            await pg.click("form[action='/consent'] button"); await pg.wait_for_load_state(); continue
        if await pg.query_selector("#erp-access-gate"):
            num=(await pg.get_attribute("#erp-receipt","aria-label")).split(":",1)[1].strip()
            await pg.eval_on_selector("#erp-access-gate input[type=range]","e=>{e.value=100;e.dispatchEvent(new Event('input',{bubbles:true}))}")
            await pg.check("#erp-access-gate > label input[type=checkbox]")
            await pg.fill("input[name=receipt]",num); await pg.check("input[name=acknowledged]")
            await pg.click("form[action='/notice'] button[type=submit]"); await pg.wait_for_load_state(); continue
        await pg.wait_for_timeout(500); await pg.goto(BASE+"/notice")
async def login(ctx):
    pg=await ctx.new_page(); await pg.goto(BASE+"/login")
    await pg.fill("input[name=username]","u_9c3cb06a5d21b197"); await pg.fill("input[name=password]","vuUcG2MsDEafLhoMjfS5")
    await pg.click("button[type=submit]"); await pg.wait_for_load_state(); await gate(pg); return pg
async def dump(pg,name,snap=True):
    await pg.wait_for_timeout(1000); await pg.screenshot(path=f"{name}.png"); open(f"{name}.html","w").write(await pg.content())
    print("=== URL",pg.url)
    if snap: print(await pg.locator("body").aria_snapshot())
async def main():
    async with async_playwright() as p:
        b=await p.chromium.launch(); ctx=await b.new_context(viewport={"width":1280,"height":800})
        pg=await login(ctx); await dump(pg,"erp_home"); await ctx.storage_state(path="erp_state.json")
        for path in sys.argv[1:]:
            await pg.goto(BASE+path); await gate(pg); await dump(pg,"erp_"+path.strip("/").replace("/","_").replace("?","_")[:40])
        await b.close()
if __name__=="__main__": asyncio.run(main())
